content:
{
  "concepts": [
    {
      "name": "数学对象",
      "aliases": [],
      "boundary": "满足可加可缩性质的数学对象",
      "domain": "泛函分析"
    },
    {
      "name": "Banach空间",
      "aliases": ["Banach空间"],
      "boundary": "完备赋范空间",
      "domain": "泛函分析"
    },
    {
      "name": "欧氏范数",
      "aliases": [],
      "boundary": "定义为‖x‖ = √⟨x,x⟩的范数",
      "domain": "线性代数"
    },
    {
      "name": "基",
      "aliases": ["基"],
      "boundary": "向量空间中的基，连接第9章和第13章",
      "domain": "线性代数"
    },
    {
      "name": "维度",
      "aliases": ["维度", "维数"],
      "boundary": "有限与无限是第一个大分岔",
      "domain": "线性代数"
    },
    {
      "name": "拓扑空间",
      "aliases": [],
      "boundary": "没有距离但能描述连续性概念的空间",
      "domain": "拓扑学"
    },
    {
      "name": "向量空间公理",
      "aliases": [],
      "boundary": "包括单位标量公理：1·u = u",
      "domain": "线性代数"
    },
    {
      "name": "内积空间",
      "aliases": [],
      "boundary": "附加结构是内积，有角度和正交性，完备版本是Hilbert空间",
      "domain": "泛函分析"
    },
    {
      "name": "完备性",
      "aliases": [],
      "boundary": "Cauchy列有极限表示没有“洞”",
      "domain": "泛函分析"
    },
    {
      "name": "正交投影",
      "aliases": [],
      "boundary": "找到子空间中最接近某点的元素",
      "domain": "泛函分析"
    },
    {
      "name": "度量空间",
      "aliases": [],
      "boundary": "度量空间的进一步推广，丢掉了距离数值，只保留开集",
      "domain": "拓扑学"
    },
    {
      "name": "不完备的空间",
      "aliases": [],
      "boundary": "不完备的空间完备化后得到 L^1[0,1]",
      "domain": "泛函分析"
    },
    {
      "name": "向量空间",
      "aliases": [],
      "boundary": "附加结构是线性运算，有基、维度、线性变换，应用领域是线性代数",
      "domain": "线性代数"
    },
    {
      "name": "正交",
      "aliases": [],
      "boundary": "x ⟂ y 当且仅当 ⟨x, y⟩ = 0",
      "domain": "泛函分析"
    },
    {
      "name": "赋范空间",
      "aliases": [],
      "boundary": "在向量空间上叠加一个范数||·||: V→R≥0",
      "domain": "泛函分析"
    },
    {
      "name": "完备度量空间",
      "aliases": [],
      "boundary": "度量空间的完备版本",
      "domain": "泛函分析"
    },
    {
      "name": "L^2[a,b]",
      "aliases": [],
      "boundary": "内积是⟨f,g⟩=∫f g的共轭，完备基是三角函数族",
      "domain": "泛函分析"
    },
    {
      "name": "内积",
      "aliases": ["inner product"],
      "boundary": "对第一个变量是线性的",
      "domain": "线性代数"
    },
    {
      "name": "维度dim V",
      "aliases": ["维度"],
      "boundary": "定义为任何一组基中的向量个数",
      "domain": "线性代数"
    },
    {
      "name": "Hilbert空间",
      "aliases": ["Hilbert空间"],
      "boundary": "完备内积空间，能统一描述从量子态到声波的一切",
      "domain": "泛函分析"
    },
    {
      "name": "标量乘法的结合律",
      "aliases": [],
      "boundary": "(cd)u = c(du)",
      "domain": "线性代数"
    },
    {
      "name": "欧几里得空间 R^n",
      "aliases": ["R^n"],
      "boundary": "定义在实数域上的 n 维向量空间",
      "domain": "几何"
    },
    {
      "name": "切比雪夫距离",
      "aliases": [],
      "boundary": "d∞(x,y)=max_i|xi-yi|",
      "domain": "度量空间"
    },
    {
      "name": "加法交换群公理",
      "aliases": [],
      "boundary": "u+v=v+u, (u+v)+w=u+(v+w), 存在零向量0和负向量-v",
      "domain": "线性代数"
    },
    {
      "name": "有限维与无限维",
      "aliases": [],
      "boundary": "向量空间的第一个大分岔口",
      "domain": "线性代数"
    },
    {
      "name": "范数",
      "aliases": ["norm"],
      "boundary": "自然导出距离：d(x,y)=||x-y||",
      "domain": "泛函分析"
    },
    {
      "name": "正交基",
      "aliases": [],
      "boundary": "用一组相互垂直的基向量表示空间中任何元素",
      "domain": "线性代数"
    },
    {
      "name": "度量空间",
      "aliases": ["metric space"],
      "boundary": "一个集合X配上一个距离函数d: X×X → R≥0",
      "domain": "拓扑学"
    },
    {
      "name": "C[0,1]",
      "aliases": [],
      "boundary": "在L1范数下不是完备的",
      "domain": "泛函分析"
    },
    {
      "name": "R^n的内积",
      "aliases": [],
      "boundary": "⟨x,y⟩=∑x_i y_i, 完备基是标准基e_i",
      "domain": "线性代数"
    },
    {
      "name": "内积的正定性",
      "aliases": [],
      "boundary": "⟨x,x⟩≥0，且⟨x,x⟩=0当且仅当x=0",
      "domain": "线性代数"
    },
    {
      "name": "层级关系",
      "aliases": [],
      "boundary": "贯穿全章的地图",
      "domain": "泛函分析"
    },
    {
      "name": "欧氏空间",
      "aliases": ["Euclidean space"],
      "boundary": "\"满配\"——什么结构都有",
      "domain": "几何"
    },
    {
      "name": "向量空间公理",
      "aliases": ["向量空间公理"],
      "boundary": "集合 V 配备加法运算和标量乘法运算",
      "domain": "线性代数"
    },
    {
      "name": "L1范数",
      "aliases": [],
      "boundary": "在L1范数下，连续函数空间中存在Cauchy列收敛到不连续的函数",
      "domain": "泛函分析"
    },
    {
      "name": "三角不等式",
      "aliases": [],
      "boundary": "d(x,z)≤d(x,y)+d(y,z)",
      "domain": "度量空间"
    },
    {
      "name": "空间",
      "aliases": ["数学空间"],
      "boundary": "集合加上附加结构",
      "domain": "泛函分析"
    },
    {
      "name": "欧几里得空间",
      "aliases": ["欧氏空间"],
      "boundary": "有全部以上附加结构，没有单独的关键概念，应用领域是几何和物理",
      "domain": "几何"
    },
    {
      "name": "拓扑（由度量诱导）",
      "aliases": [],
      "boundary": "以开球B(x,r)={y|d(x,y)<r}生成开集",
      "domain": "拓扑学"
    },
    {
      "name": "欧氏距离",
      "aliases": ["欧几里得距离"],
      "boundary": "d2(x,y)=√∑(xi-yi)^2",
      "domain": "几何"
    },
    {
      "name": "内积（点积）",
      "aliases": ["点积"],
      "boundary": "定义为 ⟨x,y⟩ = ∑_{i=1}^n x_i y_i",
      "domain": "线性代数"
    },
    {
      "name": "欧氏空间性质",
      "aliases": [],
      "boundary": "范数的平方等于内积，距离等于范数之差",
      "domain": "几何"
    },
    {
      "name": "Cauchy列",
      "aliases": ["Cauchy列"],
      "boundary": "对任意ε>0，存在N，使得当m,n>N时，有||x_m - x_n||<ε",
      "domain": "泛函分析"
    },
    {
      "name": "完备空间",
      "aliases": [],
      "boundary": "每个Cauchy列都收敛到空间内的一个点",
      "domain": "泛函分析"
    },
    {
      "name": "ℓ^2",
      "aliases": [],
      "boundary": "内积是⟨x,y⟩=∑x_i y_i的共轭，完备基是e_i",
      "domain": "泛函分析"
    },
    {
      "name": "空间的谱系",
      "aliases": [],
      "boundary": "2.7节标题",
      "domain": "泛函分析"
    },
    {
      "name": "标准基",
      "aliases": ["标准基"],
      "boundary": "R^n的标准基是e1,...,en",
      "domain": "线性代数"
    },
    {
      "name": "次数≤n的多项式空间P_n",
      "aliases": ["P_n"],
      "boundary": "基是{1,x,x^2,...,x^n}",
      "domain": "线性代数"
    },
    {
      "name": "距离公理",
      "aliases": [],
      "boundary": "三角不等式是最关键的一条",
      "domain": "度量空间"
    },
    {
      "name": "范数齐次性",
      "aliases": [],
      "boundary": "||αx||=|α|·||x||",
      "domain": "泛函分析"
    },
    {
      "name": "内积诱导范数",
      "aliases": [],
      "boundary": "||x||=sqrt(⟨x,x⟩)",
      "domain": "线性代数"
    },
    {
      "name": "共轭对称性",
      "aliases": [],
      "boundary": "⟨x,y⟩=⟨y,x⟩的共轭",
      "domain": "线性代数"
    },
    {
      "name": "可加可缩",
      "aliases": [],
      "boundary": "等于线性世界",
      "domain": "线性代数"
    },
    {
      "name": "Hamming距离",
      "aliases": [],
      "boundary": "不同位置的个数",
      "domain": "度量空间"
    },
    {
      "name": "R^n在L2范数下",
      "aliases": [],
      "boundary": "完备的，属于Banach空间",
      "domain": "泛函分析"
    },
    {
      "name": "C[0,1]在无穷范数下",
      "aliases": [],
      "boundary": "完备的，属于Banach空间",
      "domain": "泛函分析"
    },
    {
      "name": "ℓ^p",
      "aliases": [],
      "boundary": "在p范数下是完备的，属于Banach空间",
      "domain": "泛函分析"
    },
    {
      "name": "欧几里得结构",
      "aliases": [],
      "boundary": "包含线性结构和内积",
      "domain": "几何"
    },
    {
      "name": "曼哈顿距离",
      "aliases": [],
      "boundary": "d1(x,y)=∑|xi-yi|",
      "domain": "度量空间"
    },
    {
      "name": "集合",
      "aliases": ["set"],
      "boundary": "没有附加结构，关键概念是元素",
      "domain": "集合论"
    },
    {
      "name": "范数非负性",
      "aliases": [],
      "boundary": "||x||≥0，且||x||=0当且仅当x=0",
      "domain": "泛函分析"
    },
    {
      "name": "Fourier级数",
      "aliases": ["Fourier级数"],
      "boundary": "三角函数基上的正交投影",
      "domain": "泛函分析"
    },
    {
      "name": "标量乘法的分配律",
      "aliases": [],
      "boundary": "c(u+v)=cu+cv, (c+d)u=cu+du",
      "domain": "线性代数"
    },
    {
      "name": "离散度量",
      "aliases": [],
      "boundary": "d(x,y)=0若x=y，否则为1",
      "domain": "度量空间"
    },
    {
      "name": "范数三角不等式",
      "aliases": [],
      "boundary": "||x+y||≤||x||+||y||",
      "domain": "泛函分析"
    },
    {
      "name": "空间 = 集合 + 结构",
      "aliases": [],
      "boundary": "不同结构导致不同空间感",
      "domain": "泛函分析"
    },
    {
      "name": "维度（基的大小相同）",
      "aliases": [],
      "boundary": "所有基的大小都相同",
      "domain": "线性代数"
    },
    {
      "name": "距离对称性",
      "aliases": [],
      "boundary": "d(x,y)=d(y,x)",
      "domain": "度量空间"
    },
    {
      "name": "内积空间正交性",
      "aliases": [],
      "boundary": "可以定义垂直",
      "domain": "泛函分析"
    },
    {
      "name": "内积映射",
      "aliases": [],
      "boundary": "⟨·,·⟩ 是从 V×V 到 ℝ（或 ℂ）的映射",
      "domain": "线性代数"
    },
    {
      "name": "图最短路径距离",
      "aliases": [],
      "boundary": "最少边数",
      "domain": "图论"
    },
    {
      "name": "本章关键点汇总",
      "aliases": [],
      "boundary": "2.8节标题",
      "domain": "泛函分析"
    },
    {
      "name": "标量乘法",
      "aliases": [],
      "boundary": "c·(x_i) = (c x_i)",
      "domain": "线性代数"
    },
    {
      "name": "向量加法",
      "aliases": [],
      "boundary": "(x_i) + (y_i) = (x_i + y_i)",
      "domain": "线性代数"
    },
    {
      "name": "赋范空间自动成为度量空间",
      "aliases": [],
      "boundary": "(V, ||·||) 构成赋范空间，也自动成为度量空间",
      "domain": "泛函分析"
    },
    {
      "name": "连续函数空间C[0,1]",
      "aliases": ["C[0,1]"],
      "boundary": "无限维，没有有限基",
      "domain": "泛函分析"
    },
    {
      "name": "C^n",
      "aliases": [],
      "boundary": "内积是⟨x,y⟩=∑x_i y_i的共轭，完备基是标准基",
      "domain": "线性代数"
    },
    {
      "name": "三维空间 ℝ³",
      "aliases": [],
      "boundary": "最熟悉的空间",
      "domain": "几何"
    },
    {
      "name": "欧氏空间结构",
      "aliases": [],
      "boundary": "同时拥有线性、距离、内积三种结构",
      "domain": "几何"
    },
    {
      "name": "距离正定性",
      "aliases": [],
      "boundary": "d(x,y)≥0，且d(x,y)=0当且仅当x=y",
      "domain": "度量空间"
    }
  ]
}
